const SRC = {
  adiletRu: 'https://adilet.zan.kz/rus/docs/V2600038645',
  adiletKz: 'https://adilet.zan.kz/kaz/docs/V2600038645',
  mirrorRu: 'https://zakon.uchet.kz/rus/docs/V2600038645',
  mirrorKz: 'https://zakon.uchet.kz/kaz/docs/V2600038645',
};
const ACTS = { 272: 'V080005229_', 338: 'V090005750_', 125: 'V080005191_', 564: 'V1800017553', 348: 'V2200029031', 500: 'V1200008170', 473: 'V2200030721', 70: 'V1600013272', 93: 'V1600013227', 355: 'V1700015584', 349: 'V2300033682', 399: 'V2200029767', 130: 'V2000020317', 253: 'V2300033285', 190: 'V2000020619' };
const ACT_OF = { 2: [272, 355, 253, 190], 3: [338], 17: [125], 4: [348], 6: [473], 7: [473], 8: [564], 9: [348], 10: [500, 348], 11: [399], 16: [348], 18: [130], 22: [348], 23: [349], 26: [93], 29: [70] };

// =====================================================================================
//  Render helpers (bound to one render call)
// =====================================================================================
function kit(lang, ctx) {
  const { ui, L, href, docById } = ctx;
  const esc = ui.esc;
  const crit = (n) => CRIT.find((c) => c.n === n);
  const dirOf = (n) => DIRS.find((d) => d.crit.includes(n));
  const evOf = (c) => c.ev.map((e) => (e.ref ? docById(e.ref) : e)).filter(Boolean);
  const isUp = (d) => !!(d.file || d.url);
  const stat = (list) => { const up = list.filter(isUp).length; return { up, total: list.length, pct: list.length ? Math.round((up / list.length) * 100) : 0 }; };
  const uniq = (list) => [...new Map(list.map((d) => [d.id, d])).values()];
  const dirDocs = (d) => uniq(d.crit.flatMap((n) => evOf(crit(n))));
  const allDocs = () => uniq(CRIT.flatMap(evOf));
  const reportsIn = (ns) => ns.filter((n) => REPORTS[n] && REPORTS[n].file).length;
  const scoredIn = (ns) => ns.filter((n) => SCORES[n]).length;
  const allN = CRIT.map((c) => c.n);
  const anchor = (n) => `${href(`self-${dirOf(n).n}`)}#k${n}`;
  const levelName = (s) => L((LEVELS.find((l) => l.score === s) || {}).name);
  /** "4 өлшемшарт / 4 критерия / 4 criteria" — correct number agreement in each language. */
  const critN = (k) => {
    if (lang === 'kz') return `${k} өлшемшарт`;
    if (lang === 'en') return `${k} ${k === 1 ? 'criterion' : 'criteria'}`;
    const m10 = k % 10, m100 = k % 100;
    return `${k} ${m10 === 1 && m100 !== 11 ? 'критерий' : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? 'критерия' : 'критериев'}`;
  };
  const T = {
    docs: X('Растайтын құжаттар', 'Подтверждающие документы', 'Supporting documents'),
    reports: X('Талдамалық анықтамалар', 'Аналитические справки', 'Analytic reports'),
    scores: X('Өзін-өзі бағалау балдары', 'Баллы самооценки', 'Self-scores'),
    notScored: X('бағаланбаған', 'не оценено', 'not scored'),
    of: X('ішінен', 'из', 'of'),
  };

  /** "ruler" meter: label, value text, bar. */
  const meter = (label, up, total, { cls = '' } = {}) => {
    const pct = total ? Math.round((up / total) * 100) : 0;
    return `<div class="sa-meter${cls ? ' ' + cls : ''}"><p class="sa-meter__row"><span class="sa-meter__label">${L(label)}</span><span class="sa-meter__val"><b>${up}</b>/${total}</span></p><div class="sa-meter__bar" role="img" aria-label="${esc(`${L(label)}: ${up} / ${total} (${pct}%)`)}"><span style="width:${pct}%"></span></div></div>`;
  };
  /** progress ring (SVG) */
  const ring = (pct, big, small) => {
    const r = 52, c = 2 * Math.PI * r, off = c * (1 - pct / 100);
    return `<div class="sa-ring"><svg viewBox="0 0 120 120" aria-hidden="true" focusable="false"><circle class="sa-ring__track" cx="60" cy="60" r="${r}"/><circle class="sa-ring__val" cx="60" cy="60" r="${r}" stroke-dasharray="${c.toFixed(2)}" stroke-dashoffset="${off.toFixed(2)}"/></svg><p class="sa-ring__txt"><b>${big}</b><span>${small}</span></p></div>`;
  };
  const scoreBadge = (n) => (SCORES[n]
    ? `<span class="sa-score sa-score--${SCORES[n]}"><b>${SCORES[n]}</b> · ${esc(levelName(SCORES[n]))}</span>`
    : `<span class="sa-score sa-score--none">${ui.icon('hourglass', { size: 14 })}<span>${L(T.notScored)}</span></span>`);
  const actLink = (no) => ui.extLink(`https://adilet.zan.kz/${lang === 'kz' ? 'kaz' : 'rus'}/docs/${ACTS[no]}`, L(X(`№${no} бұйрық`, `приказ №${no}`, `order No. ${no}`)));

  return { critN, ui, L, href, esc, crit, dirOf, evOf, isUp, stat, dirDocs, allDocs, reportsIn, scoredIn, allN, anchor, levelName, T, meter, ring, scoreBadge, actLink };
}

